import { readFileSync } from 'node:fs';

const records = JSON.parse(readFileSync(new URL('./records.json', import.meta.url), 'utf8'));

const TOOLS = [
  {
    name: 'search_records',
    description: 'Search records by case-insensitive name match.',
    inputSchema: {
      type: 'object',
      properties: {
        query: { type: 'string' },
        limit: { type: 'integer', minimum: 1, maximum: 4, default: 2 }
      },
      required: ['query'],
      additionalProperties: false
    }
  }
];

export async function listTools() {
  return TOOLS;
}

export async function callTool(name, args = {}) {
  const tool = TOOLS.find(t => t.name === name);
  if (!tool) {
    const err = new Error('Unknown tool: ' + name);
    err.code = -32602;
    throw err;
  }
  // Validate arguments
  const { query, limit = 2 } = args;
  // Check for extra properties
  const allowed = Object.keys(tool.inputSchema.properties);
  for (const key of Object.keys(args)) {
    if (!allowed.includes(key)) {
      const err = new Error('Unknown argument: ' + key);
      err.code = -32602;
      throw err;
    }
  }
  if (typeof query !== 'string') {
    const err = new Error('query must be a string');
    err.code = -32602;
    throw err;
  }
  let lim = limit;
