    const err = new Error('limit must be an integer between 1 and 4');
    err.code = -32602;
    throw err;
  }
  const lower = query.toLowerCase();
  const matches = records.filter(r => r.name.toLowerCase().includes(lower));
  const result = matches.slice(0, lim);
  return {
    content: [{ type: 'text', text: JSON.stringify({ records: result }) }]
  };
}
